<?php if (!$rows): ?><div class="empty-state"><span class="empty-icon"><?= icon('search') ?></span><h3>Aucune intervention trouvée</h3><p>Essayez d’autres filtres ou créez votre première intervention.</p><a class="button secondary" href="<?= e(url('reports')) ?>">Réinitialiser les filtres</a></div><?php else: ?>
<div class="table-scroll"><table><thead><tr><th scope="col">INTERVENTION</th><th scope="col">INSTALLATION</th><th scope="col">PRIORITÉ</th><th scope="col">STATUT</th><th scope="col">DATE</th><th scope="col"><span class="sr-only">Consulter</span></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><a class="report-title" href="<?= e(url('report', ['id'=>$r['id']])) ?>"><span class="report-ref"><?= e(report_ref($r['id'])) ?></span><strong><?= e($r['title']) ?></strong></a><span class="location"><?= icon('pin') ?><?= e($r['location']) ?></span></td><td><span class="table-category"><?= icon(category_icon($r['category'])) ?><?= e($r['category']) ?></span></td><td><?= badge($r['priority']) ?></td><td><?= badge($r['status']) ?></td><td class="table-date"><?= date_fr($r['created_at']) ?></td><td><a class="table-arrow" href="<?= e(url('report', ['id'=>$r['id']])) ?>" aria-label="Consulter <?= e(report_ref($r['id'])) ?>"><?= icon('chevron') ?></a></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
